SELECT emp.id, emp.manager_id AS employee_manager_id, emp.full_name AS employee_full_name, emp.email AS employee_email, mgr.full_name AS manager_full_name, mgr.email AS manager_email, mgr.is_remote AS manager_is_remote FROM employees emp LEFT OUTER JOIN employees mgr ON emp.manager_id = mgr.id WHERE mgr.dept_id IN (7, 30, 34) AND emp.job_title IN ('Engineer', 'Analyst', 'Intern') ORDER BY emp.full_name, id LIMIT 50
